#include <fstream>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>
using namespace std;
// Educational ATM simulator only. Uses fictional account data stored locally.
class Account{string number,demoPin;double balance{};int failures{};vector<string>history;public:Account()=default;Account(string n,string p,double b=0):number(move(n)),demoPin(move(p)),balance(b){}const string&no()const{return number;}bool login(const string&p){if(failures>=3)return false;if(p==demoPin){failures=0;return true;}++failures;return false;}bool locked()const{return failures>=3;}double getBalance()const{return balance;}void deposit(double x){if(x>0){balance+=x;history.push_back("deposit "+to_string(x));}}bool withdraw(double x){if(x<=0||x>balance)return false;balance-=x;history.push_back("withdraw "+to_string(x));return true;}void showHistory()const{for(auto&h:history)cout<<h<<'\n';}string serialize()const{return number+"|"+demoPin+"|"+to_string(balance);}};
class ATM{vector<Account>accounts;Account*find(const string&n){for(auto&a:accounts)if(a.no()==n)return&a;return nullptr;}public:void load(){ifstream in("accounts.txt");string l;while(getline(in,l)){stringstream s(l);string n,p,b;getline(s,n,'|');getline(s,p,'|');getline(s,b);if(!n.empty())accounts.emplace_back(n,p,b.empty()?0:stod(b));}}void save()const{ofstream out("accounts.txt");for(auto&a:accounts)out<<a.serialize()<<'\n';}void create(){string n,p;cout<<"Fictional account number: ";cin>>n;if(find(n)){cout<<"Duplicate.\n";return;}cout<<"Demo PIN: ";cin>>p;accounts.emplace_back(n,p);}void session(){string n,p;cout<<"Account: ";cin>>n;auto*a=find(n);if(!a)return;bool ok=false;for(int i=0;i<3&&!a->locked();++i){cout<<"Demo PIN: ";cin>>p;if(a->login(p)){ok=true;break;}cout<<"Incorrect.\n";}if(!ok){cout<<"Locked/authentication failed.\n";return;}for(;;){cout<<"1 Deposit 2 Withdraw 3 Balance 4 History 0 Logout\n";int c;cin>>c;if(c==0)break;double x;if(c==1){cin>>x;a->deposit(x);}else if(c==2){cin>>x;if(!a->withdraw(x))cout<<"Insufficient balance.\n";}else if(c==3)cout<<a->getBalance()<<'\n';else if(c==4)a->showHistory();save();}}void run(){load();for(;;){cout<<"\nATM Simulator\n1 Create fictional account 2 Login 0 Exit\n";int c;if(!(cin>>c)||c==0){save();break;}if(c==1)create();else if(c==2)session();}}};int main(){ATM{}.run();}
